#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Entities
{
    public abstract class TeleporterBuff : BuffDefinition
    {
        public TeleporterBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(ColorModifier.Override(EngineEntityProps.COLOR_OFFSET, PROP_COLOR_OFFSET));
            AddModifier(new IntModifier(VanillaEntityProps.WATER_INTERACTION, IntegerOperator.Set, WaterInteraction.NONE));
            AddModifier(new IntModifier(VanillaEntityProps.AIR_INTERACTION, IntegerOperator.Set, WaterInteraction.NONE));
            AddModifier(new Vector3Modifier(EngineEntityProps.MODEL_POSITION_OFFSET, NumberOperator.Add, PROP_MODEL_POSITION_OFFSET));
            AddModifier(new Vector3Modifier(EngineEntityProps.DISPLAY_SCALE, NumberOperator.Multiply, PROP_DISPLAY_SCALE));
        }
        public override void OnCreate(Buff buff)
        {
            base.OnCreate(buff);
            SetTimer(buff, new FrameTimer(MAX_FRAME));
            SetColorOffset(buff, Color.white);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var timer = GetTimer(buff);
            if (timer == null)
            {
                buff.Remove();
                return;
            }
            timer.Run();
            if (IsUp)
            {
                if (timer.Frame >= SQUASH_FRAME)
                {
                    var t = 1 - (timer.Frame - SQUASH_FRAME) / (float)SQUASH_DURATION;
                    var x = Mathf.Lerp(1, SQUASH_X_SCALE, t);
                    var y = Mathf.Lerp(1, SQUASH_Y_SCALE, t);
                    SetDisplayScale(buff, new Vector3(x, y, 1));
                    SetModelPositionOffset(buff, Vector3.zero);
                }
                else if (timer.Frame >= EXTEND_FRAME)
                {
                    var t = 1 - (timer.Frame - EXTEND_FRAME) / (float)EXTEND_DURATION;
                    var x = Mathf.Lerp(SQUASH_X_SCALE, EXTEND_X_SCALE, t);
                    var y = Mathf.Lerp(SQUASH_Y_SCALE, EXTEND_Y_SCALE, t);
                    SetDisplayScale(buff, new Vector3(x, y, 1));

                    var yOffset = Mathf.Lerp(0, MAX_Y_OFFSET, t);
                    SetModelPositionOffset(buff, new Vector3(0, yOffset, 0));
                }
            }
            else
            {
                if (timer.Frame >= FALL_FRAME)
                {
                    var t = 1 - (timer.Frame - FALL_FRAME) / (float)FALL_DURATION;
                    var x = Mathf.Lerp(EXTEND_X_SCALE, SQUASH_X_SCALE, t);
                    var y = Mathf.Lerp(EXTEND_Y_SCALE, SQUASH_Y_SCALE, t);
                    SetDisplayScale(buff, new Vector3(x, y, 1));

                    var yOffset = Mathf.Lerp(MAX_Y_OFFSET, 0, t);
                    SetModelPositionOffset(buff, new Vector3(0, yOffset, 0));
                }
                else if (timer.Frame >= LAND_FRAME)
                {
                    var t = 1 - (timer.Frame - LAND_FRAME) / (float)LAND_DURATION;
                    var x = Mathf.Lerp(SQUASH_X_SCALE, 1, t);
                    var y = Mathf.Lerp(SQUASH_Y_SCALE, 1, t);
                    SetDisplayScale(buff, new Vector3(x, y, 1));
                    SetModelPositionOffset(buff, Vector3.zero);
                }
            }
            if (timer.Expired)
            {
                OnFinished(buff);
                buff.Remove();
            }
        }
        protected virtual void OnFinished(Buff buff)
        {

        }
        public static FrameTimer? GetTimer(Buff buff) => buff.GetProperty<FrameTimer>(PROP_TIMER);
        public static void SetTimer(Buff buff, FrameTimer? value) => buff.SetProperty(PROP_TIMER, value);
        public static Vector3 GetDisplayScale(Buff buff) => buff.GetProperty<Vector3>(PROP_DISPLAY_SCALE);
        public static void SetDisplayScale(Buff buff, Vector3 value) => buff.SetProperty(PROP_DISPLAY_SCALE, value);
        public static Color GetColorOffset(Buff buff) => buff.GetProperty<Color>(PROP_COLOR_OFFSET);
        public static void SetColorOffset(Buff buff, Color value) => buff.SetProperty(PROP_COLOR_OFFSET, value);
        public static Vector3 GetModelPositionOffset(Buff buff) => buff.GetProperty<Vector3>(PROP_MODEL_POSITION_OFFSET);
        public static void SetModelPositionOffset(Buff buff, Vector3 value) => buff.SetProperty(PROP_MODEL_POSITION_OFFSET, value);

        public const int MAX_FRAME = 6;

        public const int SQUASH_FRAME = MAX_FRAME * 2 / 3;
        public const int EXTEND_FRAME = 0;
        public const int SQUASH_DURATION = MAX_FRAME - SQUASH_FRAME;
        public const int EXTEND_DURATION = SQUASH_FRAME;

        public const int FALL_FRAME = MAX_FRAME / 3;
        public const int LAND_FRAME = 0;
        public const int FALL_DURATION = MAX_FRAME - FALL_FRAME;
        public const int LAND_DURATION = FALL_FRAME;

        public const float SQUASH_X_SCALE = 2f;
        public const float SQUASH_Y_SCALE = 0.5f;
        public const float EXTEND_X_SCALE = 0f;
        public const float EXTEND_Y_SCALE = 100f;

        public const float MAX_Y_OFFSET = 300;

        public const string PROPERTY_REGION = "teleporter_buff";

        public bool IsUp { get; protected set; }
        [PropertyRegistry(PROPERTY_REGION)]
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
        [PropertyRegistry(PROPERTY_REGION)]
        public static readonly VanillaBuffPropertyMeta<Vector3> PROP_MODEL_POSITION_OFFSET = new VanillaBuffPropertyMeta<Vector3>("model_position_offset", Vector3.zero);
        [PropertyRegistry(PROPERTY_REGION)]
        public static readonly VanillaBuffPropertyMeta<Vector3> PROP_DISPLAY_SCALE = new VanillaBuffPropertyMeta<Vector3>("display_scale", Vector3.one);
        [PropertyRegistry(PROPERTY_REGION)]
        public static readonly VanillaBuffPropertyMeta<Color> PROP_COLOR_OFFSET = new VanillaBuffPropertyMeta<Color>("color_offset");
    }
}
